AugAssignConditional:
import subprocess
class Box:
    pass
box = Box()
box.cbs = []
def run():
    subprocess.run(["pacman", "-S", "r23y-aug-cond"])
def register(callback, flag):
    if flag:
        box.cbs += [callback]
register(run, True)
for f in box.cbs:
    f()

